static bool ts_lex(TSLexer *lexer, TSStateId state) {
  START_LEXER();
  eof = lexer->eof(lexer);
  switch (state) {
    case 0:
      if (eof) ADVANCE(3);
      if (lookahead == '\n') ADVANCE(4);
      if (lookahead == '\r') ADVANCE(2);
      if (lookahead != 0) ADVANCE(1);
      END_STATE();
    case 1:
      END_STATE();
    case 2:
      if (lookahead == '\n') ADVANCE(4);
      END_STATE();
    case 3:
      ACCEPT_TOKEN(ts_builtin_sym_end);
      END_STATE();
    case 4:
      ACCEPT_TOKEN(sym_line_ending);
      END_STATE();
    default:
      return false;
  }
}

